// Build CE Lead alert payload for Grok Watchdog
const body = $json.body || $json;

const leadId = body.leadId || body.id || `lead_${Date.now()}`;
const correlationId = body.correlationId || body.correlation_id || `ce-lead-${Date.now()}`;
const source = body.source || 'unknown';
const name = body.name || body.leadName || 'Anonymous';
const email = body.email || 'N/A';
const score = body.score || body.leadScore || 0;
const channel = body.channel || 'direct';
const notes = body.notes || body.message || '';
const status = body.status || 'new';

const text = [
  `NEW CE LEAD`,
  ``,
  `Lead: ${name}`,
  `Email: ${email}`,
  `Score: ${score}`,
  `Source: ${source}`,
  `Channel: ${channel}`,
  notes ? `Notes: ${notes}` : '',
  ``,
  `ID: ${leadId}`,
  `cid: ${correlationId}`,
  `Time: ${new Date().toISOString()}`
].filter(Boolean).join('\n');

return [{ json: { text, leadId, name, score, correlationId, status, error: null } }];
